  function getTopDocument() {
    try {
      return window.top?.document || document;
    } catch {
      return document;
    }
  }

  /**
   * Run UI work on the visible top window. Firefox suspends requestAnimationFrame
   * inside Tavern Helper's display:none script iframe, so keep a timer fallback.
   */
  function scheduleUiFrame(callback) {
    let completed = false;
    const runOnce = () => {
      if (completed) return;
      completed = true;
      callback();
    };
    const fallbackId = setTimeout(runOnce, 50);

    try {
      const uiWindow = getTopDocument()?.defaultView;
      if (uiWindow && typeof uiWindow.requestAnimationFrame === 'function') {
        return uiWindow.requestAnimationFrame(() => {
          clearTimeout(fallbackId);
          runOnce();
        });
      }
    } catch (error) {
      log('Top-window animation frame unavailable; using timer fallback', error);
    }

    return fallbackId;
  }

  function getST() {
    if (typeof SillyTavern !== 'undefined') return SillyTavern;
    return null;
  }

  function getChatArray() {
    const st = getST();
    if (st && Array.isArray(st.chat)) return st.chat;
    if (Array.isArray(window.chat)) return window.chat;
