        return st.messageFormatting(
          text,
          String(message?.name || ''),
          Boolean(message?.is_system),
          false,
          messageId,
          undefined,
          isReasoning
        );
      }
    } catch (error) {
      log('Streaming message formatting failed; using plain text', error);
    }
    return null;
  }

  function syncReasoningStateDom(messageDom, state) {
    if (!messageDom) return;
    messageDom.classList.toggle('reasoning', state !== 'none');
    if (state === 'thinking') {
      messageDom.setAttribute('data-reasoning-state', 'thinking');
      messageDom.setAttribute('data-is-thinking', 'true');
    } else if (state === 'done') {
      messageDom.setAttribute('data-reasoning-state', 'done');
      messageDom.removeAttribute('data-is-thinking');
    } else {
      messageDom.removeAttribute('data-reasoning-state');
      messageDom.removeAttribute('data-is-thinking');
    }
  }

  const reasoningEditToggleGuardListeners = new Map();

  function syncReasoningContentDom(details, message) {
    if (!details) return;
    // 1.19 的标题点击和控件显隐读取此标记，不能仅依赖原生节点的非空占位。
    // 依据实际思维内容同步；旧版忽略此属性，仍沿用下方的非空占位逻辑。
    if (String(message?.extra?.reasoning ?? '').trim()) {
      details.setAttribute('data-has-content', 'true');
    } else {
      details.removeAttribute('data-has-content');
    }
  }

  /**
   * 酒馆用 document 级委托处理思维标题：消息编辑态下，每次标题点击都可能再次
   * 触发思维编辑按钮。消息节点又会在编辑/重绘时被替换，所以保护必须装在文档
   * 捕获阶段，不能依赖某一个旧 header 节点上的一次性监听器。
   */
  function bindReasoningEditToggleGuard(doc) {
    if (!doc?.addEventListener || reasoningEditToggleGuardListeners.has(doc)) return;

    const onClickCapture = (event) => {
      const target = event.target;
      if (typeof target?.closest !== 'function') return;

      const ownerMessage = target.closest('.mes');
      if (!ownerMessage?.querySelector?.('#curEditTextarea')) return;

      const editors = [...ownerMessage.querySelectorAll('.reasoning_edit_textarea')];
      const activeEditor = editors.find((editor) => editor === doc.activeElement) || editors.at(-1);
      if (editors.length > 1) {
        for (const editor of editors) {
          if (editor !== activeEditor) editor.remove();
        }
      }

      // 原生编辑按钮没有防重；已有编辑框时也拦住连续点击。
      if (target.closest('.mes_reasoning_edit') && activeEditor) {
        event.preventDefault();
        event.stopImmediatePropagation();
        return;
      }

      const header = target.closest('.mes_reasoning_header');
      if (!header || !ownerMessage.contains(header)) return;
      const details = header.closest('.mes_reasoning_details');
      if (!details) return;

      // 首次从关闭态展开时保留酒馆原生行为：展开并创建唯一的思维编辑框。
      if (!activeEditor && !details.open) return;

      // 其余点击只切换当前 details，不再交给酒馆的委托编辑逻辑。
      event.preventDefault();
      event.stopImmediatePropagation();
      details.open = !details.open;
    };

    doc.addEventListener('click', onClickCapture, true);
    reasoningEditToggleGuardListeners.set(doc, onClickCapture);
  }

  function unbindReasoningEditToggleGuards() {
    for (const [doc, listener] of reasoningEditToggleGuardListeners) {
      doc.removeEventListener?.('click', listener, true);
    }
    reasoningEditToggleGuardListeners.clear();
  }

  /**
   * 流式阶段只更新已经存在的 reasoning 和正文节点，避免 updateMessageBlock
   * 反复重建消息。酒馆的消息模板会预建 reasoning 节点，只需同步显示状态。
   */
  function patchStreamingMessageDom(messageId, message, state) {
    const messageDom = findMessageDom(messageId);
    const reasoningDetailsDom = messageDom?.querySelector?.('.mes_reasoning_details');
    const nativeReasoningDom = reasoningDetailsDom?.querySelector?.('.mes_reasoning');
    if (!messageDom || !reasoningDetailsDom || !nativeReasoningDom) return false;

    messageDom.setAttribute('data-qqz-reasoning-streaming', 'true');
    syncReasoningStateDom(messageDom, state);
    reasoningDetailsDom.setAttribute('data-state', state);
    syncReasoningContentDom(reasoningDetailsDom, message);
    if (state === 'thinking' && getReasoningConfig().auto_expand) reasoningDetailsDom.open = true;

    // 酒馆会阻止打开原生 .mes_reasoning 为空的 details。流式正文显示在下方
    // 稳定节点中，因此给被隐藏的原生节点保留零宽占位，让手动展开/折叠正常工作。
    if (!nativeReasoningDom.hasChildNodes()) nativeReasoningDom.textContent = '\u200B';

    const reasoningTitleDom = messageDom.querySelector('.mes_reasoning_header_title');
    if (reasoningTitleDom) {
      reasoningTitleDom.textContent = FIXED_REASONING_TITLE;
      reasoningTitleDom.setAttribute('data-custom-title', FIXED_REASONING_TITLE);
      reasoningTitleDom.removeAttribute('data-animating');
    }

    let reasoningDom = reasoningDetailsDom.querySelector('.qqz_reasoning_stream');
    if (!reasoningDom) {
      reasoningDom = messageDom.ownerDocument.createElement('div');
      reasoningDom.className = 'qqz_reasoning_stream';
      nativeReasoningDom.insertAdjacentElement('afterend', reasoningDom);
    }

    const reasoning = String(message?.extra?.reasoning || '');
    const renderState = reasoningDom.dataset.qqzRenderState;
    if (reasoningDom.dataset.qqzReasoningRaw !== reasoning || renderState !== state) {
      const previousScrollTop = reasoningDom.scrollTop;
      const wasAtBottom = reasoningDom.scrollHeight <= reasoningDom.clientHeight
        || reasoningDom.scrollHeight - reasoningDom.scrollTop - reasoningDom.clientHeight < 8;

      if (state === 'thinking') {
        let textNode = reasoningDom.firstChild;
        if (!textNode || textNode.nodeType !== 3 || reasoningDom.childNodes.length !== 1) {
          textNode = messageDom.ownerDocument.createTextNode('');
          reasoningDom.replaceChildren(textNode);
        }
        if (textNode.nodeValue !== reasoning) textNode.nodeValue = reasoning;
      } else {
        const formatted = formatMessageForDom(messageId, message, reasoning, true);
        if (typeof formatted === 'string') reasoningDom.innerHTML = formatted;
        else reasoningDom.textContent = reasoning;
      }
      reasoningDom.dataset.qqzReasoningRaw = reasoning;
      reasoningDom.dataset.qqzRenderState = state;

      if (wasAtBottom) reasoningDom.scrollTop = reasoningDom.scrollHeight;
      else reasoningDom.scrollTop = Math.min(previousScrollTop, reasoningDom.scrollHeight);
    }

    if (state === 'done') {
      const messageTextDom = messageDom.querySelector?.('.mes_text');
      if (!messageTextDom) return false;
      const body = String(message?.extra?.display_text ?? message?.mes ?? '');
      if (messageTextDom.dataset.qqzMessageRaw !== body) {
        const formatted = formatMessageForDom(messageId, message, body, false);
        if (typeof formatted === 'string') messageTextDom.innerHTML = formatted;
        else messageTextDom.textContent = body;
        messageTextDom.dataset.qqzMessageRaw = body;
      }
    }

    return true;
  }

  function finalizeStreamingMessageDom(messageId, message) {
    const messageDom = findMessageDom(messageId);
    if (!messageDom) return;

    const reasoningDetailsDom = messageDom.querySelector('.mes_reasoning_details');
    const nativeReasoningDom = reasoningDetailsDom?.querySelector('.mes_reasoning');
    const streamingReasoningDom = reasoningDetailsDom?.querySelector('.qqz_reasoning_stream');
    syncReasoningContentDom(reasoningDetailsDom, message);
    if (nativeReasoningDom && streamingReasoningDom) {
      const reasoning = String(message?.extra?.reasoning || '');
      const formatted = formatMessageForDom(messageId, message, reasoning, true);
      if (typeof formatted === 'string') nativeReasoningDom.innerHTML = formatted;
      else nativeReasoningDom.textContent = reasoning;
      nativeReasoningDom.dataset.qqzReasoningRaw = reasoning;
      streamingReasoningDom.remove();
    }

    messageDom.removeAttribute('data-qqz-reasoning-streaming');
    if (message?.extra?.reasoning) syncReasoningStateDom(messageDom, 'done');
  }

  function injectStyleOnce(doc) {
    if (!doc || !doc.head) return;
    let style = doc.getElementById(STYLE_ID);
    if (!style) {
      style = doc.createElement('style');
      style.id = STYLE_ID;
      doc.head.appendChild(style);
      log('style created', { inTop: doc === getTopDocument() });
    }
    style.textContent = `${REASONING_CSS}\n${REASONING_THEME_CSS}`;
  }

  function injectStyle() {
    injectStyleOnce(document);
    injectStyleOnce(getTopDocument());
    log('style injected', { cssLength: REASONING_CSS.length + REASONING_THEME_CSS.length });
  }

  function removeStyle() {
    for (const doc of [document, getTopDocument()]) {
      const style = doc?.getElementById?.(STYLE_ID);
      if (style) style.remove();
    }
    log('style removed');
  }

  /**
   * 核心：流式兼容的解析逻辑 (无头优先)
   */
  function getReasoningTagPairs() {
    const config = getReasoningConfig();
    const candidates = [
      { prefix: config.prefix, suffix: config.suffix },
      { prefix: '<recorder_thinking>', suffix: '</recorder_thinking>' },
      { prefix: '<thinking>', suffix: '</thinking>' },
      { prefix: '<think>', suffix: '</think>' }
    ];
    const seen = new Set();
    return candidates.filter(({ prefix, suffix }) => {
      if (!prefix || !suffix) return false;
      const key = `${prefix}\u0000${suffix}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }

  function getLeadingRecorderEnvelope(text, limit = text.length) {
    const head = String(text || '').slice(0, Math.max(0, limit));
    return head.match(/^\s*(?:<(?:recorder_output|discussion_record|destined_discussion)(?:\s[^>]*)?>\s*)*/i)?.[0] || '';
  }

  function maskReasoningExamples(text) {
    const blank = value => value.replace(/[^\r\n]/g, ' ');
    return text
      .replace(/^[ \t]{0,3}(`{3,}|~{3,})[^\r\n]*(?:\r?\n|$)[\s\S]*?(?:^[ \t]{0,3}\1[ \t]*(?=\r?\n|$)|(?![\s\S]))/gm, blank)
      .replace(/(`+)[^\r\n]*?(?:\1|(?=\r?\n|$))/g, blank);
  }

  function extractReasoningAndClean(text, isStreaming) {
    if (typeof text !== 'string') return null;
    // Claude 可能先闭合模型原生思维通道；该孤立标签不属于 Recorder 公开裁决。
    text = text.replace(/^\s*(?:<\/(?:think|thinking)>\s*)+/i, '');
    const tagPairs = getReasoningTagPairs();
    const envelope = getLeadingRecorderEnvelope(text);
    const start = text.slice(envelope.length);
    const leadingPair = tagPairs.find(({ prefix }) => start.startsWith(prefix));
    if (!leadingPair && /^(?:[`~>]|<)/.test(start)) return null;

    // 正文起始标签也会出现在结构检查中，不能用它推断思维链已经结束。
    // 只接受闭合标签处的结构转换；代码示例中的标签不作为边界。
    const visible = maskReasoningExamples(text);
    const reasoningStart = envelope.length + (leadingPair?.prefix.length || 0);
    let closed = null;
    for (const pair of leadingPair ? [leadingPair] : tagPairs) {
      let suffixIndex = visible.indexOf(pair.suffix, reasoningStart);
      while (suffixIndex !== -1) {
        const after = visible.slice(suffixIndex + pair.suffix.length);
        const beforeOnLine = visible.slice(visible.lastIndexOf('\n', suffixIndex - 1) + 1, suffixIndex);
        const bodyFollows = /^\s*<(?:recorder_body(?:\s[^>]*)?|tp\b[^>]*|gametxt)>/i.test(after);
        const standalone = /^[\t \r]*$/.test(beforeOnLine) && /^[\t \r]*(?:\n|$)/.test(after);
        const atEnd = !isStreaming && /^\s*(?:<\/(?:recorder_output|discussion_record|destined_discussion)>\s*)*$/i.test(after);
        const inlineExample = !leadingPair && tagPairs.some(({ prefix }) => beforeOnLine.includes(prefix));
        if (!inlineExample && (bodyFollows || (leadingPair && (standalone || atEnd)))) {
          if (!closed || suffixIndex < closed.suffixIndex) closed = { ...pair, suffixIndex };
          break;
        }
        suffixIndex = visible.indexOf(pair.suffix, suffixIndex + pair.suffix.length);
      }
    }

    // 1. 已闭合的显式或无头思维块。无头时保留最外层 recorder_output，避免生成孤立闭合标签。
    if (closed) {
      const envelopePrefix = envelope;
      const reasoningPart = text.slice(reasoningStart, closed.suffixIndex);
      const cleaned = `${envelopePrefix}${text.slice(closed.suffixIndex + closed.suffix.length)}`.trim();
      const title = extractLatestHeaderByPriority(reasoningPart);
      return { reasoning: reasoningPart.trim(), cleaned, state: 'done', title, envelopePrefix };
    }

    // 2. 显式思维块尚未闭合时保留全部内容，包括被引用的正文标签。
    if (leadingPair) {
      const envelopePrefix = envelope;
      const reasoning = text.slice(reasoningStart);
      const title = extractLatestHeaderByPriority(reasoning);
      return { reasoning: reasoning.trim(), cleaned: '', state: 'thinking', title, envelopePrefix };
    }

    // Do not infer a reasoning channel from ordinary text, a Recorder body
    // boundary, or arbitrary XML. A headless prefill remains visible body text
    // until a supported closing tag arrives and is handled by the closed branch.
    return null;
  }

  function normalizeHeaderText(str) {
    return String(str || '')
      .replace(/\s+/g, ' ')
      .replace(/[\u200B-\u200D\uFEFF]/g, '')
      .trim();
  }

  function normalizeTpText(str) {
    return String(str || '')
      .replace(/[\u200B-\u200D\uFEFF]/g, '')
      .replace(/\s*\n\s*/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function extractTpInfo(text) {
    const src = String(text || '');
    if (!src || !src.includes('<tp')) return null;

    const match = src.match(/<tp\b[^>]*>\s*([^@|<]*?)\s*(?:@\s*([^@|<]*?)\s*?)?(?:\|\s*([^<]*?)\s*)?<\/tp>/i);
    if (!match) return null;

    const time = normalizeTpText(match[1]);
    const location = normalizeTpText(match[2]);
    const weather = normalizeTpText(match[3]);

    if (!time && !location && !weather) return null;
    return { time, location, weather };
  }

  function findMessageDom(messageId) {
    const selector = `#chat [mesid="${messageId}"]`;
    const inFrame = document.querySelector(selector);
    if (inFrame) return inFrame;
    const topDoc = getTopDocument();
    return topDoc?.querySelector?.(selector) || null;
  }

  function isMessageStreaming(messageId, message, chat) {
    const topDoc = getTopDocument();
    const bodyGenerating = topDoc?.body?.getAttribute?.('data-generating') === 'true';

    if (bodyGenerating) {
      for (let i = chat.length - 1; i >= 0; i--) {
        if (chat[i] && !chat[i].is_user) return i === messageId;
      }
    }

    return Boolean(message?.gen_started && !message?.gen_finished && message?.swipe_id === undefined);
  }

  function resolveDisplayTitle(state, rawTitle) {
    void rawTitle;
    if (state === 'done' || state === 'thinking') return FIXED_REASONING_TITLE;
    return '';
  }

  function clipTitle(title, maxLen = 42) {
    const t = normalizeHeaderText(title);
    if (!t) return '';
    return t.length > maxLen ? t.slice(0, maxLen) : t;
  }

  function extractLatestHeaderByPriority(text) {
    const src = String(text || '');
    if (!src) return '';

    let best = null;

    const pick = (priority, index, rawTitle) => {
      const title = normalizeHeaderText(rawTitle);
      if (!title || /^[`~!@#$%^&*()_+\-=\[\]{};:'",.<>/?|\\]+$/.test(title)) return;

      if (!best || priority > best.priority || (priority === best.priority && index > best.index)) {
        best = { priority, index, title };
      }
    };

    // 优先级 3: # 标题 / ## 标题
    {
      const re = /^(#{1,2})\s+(.+)$/gm;
      let m;
      while ((m = re.exec(src)) !== null) {
        pick(3, m.index, m[2]);
      }
    }

    // 优先级 2: **标题**（行级）
    {
      const re = /(?:^|\n)\s*\*\*([^*\n][^*\n]*?)\*\*\s*(?=\n|$)/g;
      let m;
      while ((m = re.exec(src)) !== null) {
        pick(2, m.index, m[1]);
      }
    }

    // 优先级 1: - 标题 / • 标题
    {
      const re = /^\s*(?:-|•)\s+(.+)$/gm;
      let m;
      while ((m = re.exec(src)) !== null) {
        pick(1, m.index, m[1]);
      }
    }

    return best?.title || '';
  }

  function recoverBodyFromNativeReasoning(message) {
    if (message.extra?.reasoning_type !== 'model') return false;
    const currentBody = String(message.mes ?? '');
    const onlyPlaceholder = text => /^\s*(?:\.\.\.|<StatusPlaceHolderImpl\s*\/>)?\s*$/i.test(text);
    if (!onlyPlaceholder(currentBody)) return false;
    const displayText = message.extra?.display_text;
    if (displayText != null && !onlyPlaceholder(String(displayText))) return false;

    const parsed = extractReasoningAndClean(String(message.extra.reasoning ?? ''), false);
    if (parsed?.state !== 'done') return false;
    const bodyStart = parsed.cleaned.slice(getLeadingRecorderEnvelope(parsed.cleaned).length);
    if (!/^<recorder_body(?:\s[^>]*)?>/i.test(bodyStart)) return false;

    const suffix = currentBody.trim() === '...' ? '' : currentBody.trim();
    const restored = `${parsed.cleaned}${suffix ? `\n${suffix}` : ''}`;
    message.extra.reasoning = parsed.reasoning;
    message.extra.reasoning_type = 'parsed';
    message.extra.reasoning_state = 'done';
    message.mes = restored;
    if (displayText != null) message.extra.display_text = restored;
    const swipe = Number(message.swipe_id ?? 0);
    if (Array.isArray(message.swipes) && Number.isInteger(swipe) && swipe >= 0 && swipe < message.swipes.length) {
      message.swipes[swipe] = restored;
      const swipeExtra = message.swipe_info?.[swipe]?.extra;
      if (swipeExtra && typeof swipeExtra === 'object') {
        swipeExtra.reasoning = parsed.reasoning;
        swipeExtra.reasoning_type = 'parsed';
        swipeExtra.reasoning_state = 'done';
        if (displayText != null) swipeExtra.display_text = restored;
      }
    }
    return true;
  }

  function applyReasoningToMessage(messageId, generationComplete = false) {
    const id = Number(messageId);
    if (!Number.isInteger(id) || id < 0) return;

    const chat = getChatArray();
    if (!chat) return;

    const message = chat[id];
    if (!message || message.is_user) return;

    const isStreaming = isMessageStreaming(id, message, chat);
    if ((generationComplete || !isStreaming) && recoverBodyFromNativeReasoning(message)) updateBlock(id, message);

    const messageText = String(message.mes ?? '');
    const hasVisibleReasoningMarker = getReasoningTagPairs()
      .some(({ prefix, suffix }) => messageText.includes(prefix) || messageText.includes(suffix));

    // 可见的受控 Recorder 思维链优先于模型原生 reasoning；DS 正文没有该标签，会自然进入原生分支。
    if (hasVisibleReasoningMarker || !message.extra?.reasoning) {
      const parsed = extractReasoningAndClean(messageText, isStreaming);
      if (parsed) {
        message.extra = (message.extra && typeof message.extra === 'object') ? message.extra : {};
        const previousReasoning = String(message.extra.reasoning || '');
        const previousType = message.extra.reasoning_type;
        const previousState = message.extra.reasoning_state;
        const previousTitle = message.extra.reasoning_header_title;
        const previousMessageText = String(message.mes ?? '');
        const savedEnvelopePrefix = String(message.extra.reasoning_envelope_prefix || '');
        if (parsed.state === 'thinking' && parsed.envelopePrefix) {
          message.extra.reasoning_envelope_prefix = parsed.envelopePrefix;
        }

        let cleaned = parsed.cleaned;
        const envelopePrefix = parsed.envelopePrefix || savedEnvelopePrefix;
        if (parsed.state === 'done' && envelopePrefix) {
          const normalizedPrefix = envelopePrefix.trim();
          if (normalizedPrefix && !cleaned.trimStart().startsWith(normalizedPrefix)) {
            cleaned = `${envelopePrefix}${cleaned}`.trim();
          }
          delete message.extra.reasoning_envelope_prefix;
        }

        message.extra.reasoning = parsed.reasoning;
        message.extra.reasoning_type = 'parsed';
        message.extra.reasoning_state = parsed.state;
        message.mes = cleaned;
        const swipe = Number(message.swipe_id ?? 0);
        if (Array.isArray(message.swipes) && Number.isInteger(swipe) && swipe >= 0 && swipe < message.swipes.length) message.swipes[swipe] = cleaned;

        const title = clipTitle(resolveDisplayTitle(parsed.state, parsed.title));
        const tpInfo = extractTpInfo(cleaned);
        message.extra.reasoning_header_title = title;

        const shouldUpdateBlock = previousReasoning !== parsed.reasoning
          || previousType !== 'parsed'
          || previousState !== parsed.state
          || previousTitle !== title
          || previousMessageText !== cleaned;
        if (shouldUpdateBlock) {
          const patchedInPlace = isStreaming && patchStreamingMessageDom(id, message, parsed.state);
          if (!patchedInPlace) updateBlock(id, message);
        }
        updateReasoningUIState(id, parsed.state, title, tpInfo);
        return;
      }
    }

    if (message.extra?.reasoning) {
      const nativeState = message.extra?.reasoning_state;
      const nativeBodyStarted = String(message.mes ?? '').trim().length > 0;
      const nativeReasoningDone = nativeBodyStarted || Boolean(message.extra?.reasoning_duration);
      const state = nativeReasoningDone
        ? 'done'
        : (nativeState === 'thinking' || nativeState === 'done'
            ? nativeState
            : (isStreaming ? 'thinking' : 'done'));

      const tpInfo = extractTpInfo(String(message.mes ?? ''));

      // 只从 reasoning 区块提取标题，避免在正文阶段误抓正文首行
      const titleSource = String(message.extra?.reasoning || '');
      const extracted = extractLatestHeaderByPriority(titleSource);
      const title = clipTitle(resolveDisplayTitle(state, extracted));
      if (message.extra.reasoning_header_title !== title) {
        message.extra.reasoning_header_title = title;
      }

      updateReasoningUIState(id, state, title, tpInfo);
      return;
    }

    updateReasoningUIState(id, 'none', '', null);
  }

  function updateReasoningTpMeta(messageDom, tpInfo) {
    const header = messageDom.querySelector('.mes_reasoning_header');
    if (!header) return;

    let meta = header.querySelector('.qqz_reasoning_tp_meta');
    if (!meta) {
      meta = document.createElement('div');
      meta.className = 'qqz_reasoning_tp_meta';
      meta.innerHTML = [
        '<div class="qqz_reasoning_tp_line qqz_reasoning_tp_line--time"><span class="qqz_reasoning_tp_label">时间</span><span class="qqz_reasoning_tp_value"></span></div>',
        '<div class="qqz_reasoning_tp_line qqz_reasoning_tp_line--location"><span class="qqz_reasoning_tp_label">地点</span><span class="qqz_reasoning_tp_value"></span></div>',
        '<div class="qqz_reasoning_tp_line qqz_reasoning_tp_line--weather"><span class="qqz_reasoning_tp_label">天象</span><span class="qqz_reasoning_tp_value"></span></div>'
      ].join('');
      header.appendChild(meta);
    }

    const rows = {
      time: meta.querySelector('.qqz_reasoning_tp_line--time'),
      location: meta.querySelector('.qqz_reasoning_tp_line--location'),
      weather: meta.querySelector('.qqz_reasoning_tp_line--weather')
    };

    const values = {
      time: rows.time?.querySelector('.qqz_reasoning_tp_value'),
      location: rows.location?.querySelector('.qqz_reasoning_tp_value'),
      weather: rows.weather?.querySelector('.qqz_reasoning_tp_value')
    };

    const fields = {
      time: normalizeTpText(tpInfo?.time),
      location: normalizeTpText(tpInfo?.location),
      weather: normalizeTpText(tpInfo?.weather)
    };

    let visibleCount = 0;
    for (const key of ['time', 'location', 'weather']) {
      const row = rows[key];
      const valueNode = values[key];
      const value = fields[key];
      if (!row || !valueNode) continue;

      if (value) {
        valueNode.textContent = value;
        row.hidden = false;
        visibleCount += 1;
      } else {
        valueNode.textContent = '';
        row.hidden = true;
      }
    }

    meta.hidden = visibleCount === 0;
  }

  /**
   * 强制同步 DOM 状态属性
   */
  function updateReasoningUIState(messageId, state, title, tpInfo) {
    scheduleUiFrame(() => {
      const messageDom = findMessageDom(messageId);
      if (!messageDom) return;
      // 给根节点同步酒馆原生 reasoning 类与自定义状态。
      syncReasoningStateDom(messageDom, state);
      const mesDetails = messageDom.querySelector('.mes_reasoning_details');

      if (mesDetails) {
        syncReasoningContentDom(mesDetails, getChatArray()?.[messageId]);
        if (mesDetails.getAttribute('data-state') !== state) {
          mesDetails.setAttribute('data-state', state);
        }
        const config = getReasoningConfig();
        if (state === 'thinking' && config.auto_expand) {
          if (!mesDetails.open) mesDetails.open = true;
        }
      }
      renderReasoningHeader(messageDom, state, title, tpInfo);
    });
  }

  function renderReasoningHeader(messageDom, state, title, tpInfo) {
    const mesTitle = messageDom.querySelector('.mes_reasoning_header_title');
    if (mesTitle) {
      const finalTitle = clipTitle(resolveDisplayTitle(state, title));
      const prevTitle = mesTitle.getAttribute('data-custom-title') || '';

      if (finalTitle) {
        // Keep real text as a readable fallback if pseudo-element rendering fails.
        mesTitle.textContent = finalTitle;
        if (state === 'thinking') {
          mesTitle.setAttribute('data-custom-title', finalTitle);
          mesTitle.removeAttribute('data-animating');
        } else if (prevTitle !== finalTitle) {
          mesTitle.setAttribute('data-animating', 'true');
          scheduleUiFrame(() => {
            mesTitle.setAttribute('data-custom-title', finalTitle);
            setTimeout(() => mesTitle.removeAttribute('data-animating'), 260);
          });
        }
      } else {
        mesTitle.removeAttribute('data-custom-title');
        mesTitle.removeAttribute('data-animating');
      }
    }

    updateReasoningTpMeta(messageDom, tpInfo);
  }

  function applyReasoningToAllMessages() {
    const chat = getChatArray();
    if (!chat) return;
    for (let i = 0; i < chat.length; i++) applyReasoningToMessage(i);
  }

  const pendingMessageIds = new Set();
  let streamTickScheduled = false;
  const streamingRawText = new Map();
  const streamingObservers = new Map();

  function flushScheduledMessages() {
    streamTickScheduled = false;
    const ids = [...pendingMessageIds];
    pendingMessageIds.clear();
    for (const id of ids) applyReasoningToMessage(id);
  }

  function scheduleApplyMessage(messageId) {
    const id = Number(messageId);
    if (!Number.isInteger(id) || id < 0) return;
    pendingMessageIds.add(id);
    if (streamTickScheduled) return;
    streamTickScheduled = true;
    // 同一轮事件只处理一次，并在浏览器绘制前覆盖酒馆的原始流式文本。
    if (typeof queueMicrotask === 'function') queueMicrotask(flushScheduledMessages);
    else Promise.resolve().then(flushScheduledMessages);
  }

  function stopStreamingObserver(messageId) {
    const record = streamingObservers.get(messageId);
    record?.observer?.disconnect?.();
    streamingObservers.delete(messageId);
    streamingRawText.delete(messageId);
  }

  function stopAllStreamingObservers() {
    for (const messageId of streamingObservers.keys()) stopStreamingObserver(messageId);
    streamingRawText.clear();
  }

  /**
   * STREAM_TOKEN_RECEIVED 发生在酒馆写入 chat 与 .mes_text 之前。
   * 正文清洗仍等待 .mes_text 写入；原生思维链的头部另行在绘制前同步。
   * 不在原生 reasoning 的 DOM 变化时解析正文，此时 chat 可能尚未更新。
   */
  function applyStreamingRawText(messageId, isStreaming = true) {
    const chat = getChatArray();
    const message = chat?.[messageId];
    if (!message || message.is_user) return;

    const streamedRawText = streamingRawText.get(messageId);
    // 收尾阶段（MESSAGE_RECEIVED）若当前正文比流式快照更长，说明有其它扩展
    // （如变量更新脚本）在流式结束后往正文追加了内容（占位标记等）。此时以当前
    // 正文为清洗源，避免用快照覆盖把追加内容一并抹掉；其余情况沿用流式快照，
    // 无快照时仍不处理，行为与原先一致。已清洗过的正文不含标签，会在下方返回 null。
    const currentText = typeof message.mes === 'string' ? message.mes : '';
    const rawText = !isStreaming
      && typeof streamedRawText === 'string'
      && currentText.length > streamedRawText.length
      ? currentText
      : streamedRawText;
    if (typeof rawText !== 'string') return;

    // 原生通道已经有内容时，不将普通正文或半截结构标签猜作无头思维链。
    // 预填充后若缺少起始标签，等闭合标签到达，再从完整流文本提取公开裁决。
    const markerText = rawText.replace(/^\s*(?:<\/(?:think|thinking)>\s*)+/i, '');
    const hasReasoningMarker = getReasoningTagPairs()
      .some(({ prefix, suffix }) => markerText.includes(prefix) || markerText.includes(suffix));
    if (message.extra?.reasoning_type === 'model' && message.extra?.reasoning && !hasReasoningMarker) return;

    const parsed = extractReasoningAndClean(rawText, isStreaming);
    if (!parsed) return;

    message.extra = (message.extra && typeof message.extra === 'object') ? message.extra : {};
    const savedEnvelopePrefix = String(message.extra.reasoning_envelope_prefix || '');
    if (parsed.state === 'thinking' && parsed.envelopePrefix) {
      message.extra.reasoning_envelope_prefix = parsed.envelopePrefix;
    }

    let cleaned = parsed.cleaned;
    const envelopePrefix = parsed.envelopePrefix || savedEnvelopePrefix;
    if (parsed.state === 'done' && envelopePrefix) {
      const normalizedPrefix = envelopePrefix.trim();
      if (normalizedPrefix && !cleaned.trimStart().startsWith(normalizedPrefix)) {
        cleaned = `${envelopePrefix}${cleaned}`.trim();
      }
      delete message.extra.reasoning_envelope_prefix;
    }

    message.extra.reasoning = parsed.reasoning;
    message.extra.reasoning_type = 'parsed';
    message.extra.reasoning_state = parsed.state;
    message.extra.reasoning_header_title = FIXED_REASONING_TITLE;
    message.mes = cleaned;

    // 流式阶段绝不调用 updateMessageBlock：它会让酒馆 StreamingProcessor
    // 缓存的 .mes_text 指向已被替换的旧节点，导致正文直到生成结束才重新出现。
    patchStreamingMessageDom(messageId, message, parsed.state);
    updateReasoningUIState(
      messageId,
      parsed.state,
      FIXED_REASONING_TITLE,
      extractTpInfo(cleaned)
    );
  }

  function scheduleStreamingHeader(messageId) {
    const record = streamingObservers.get(messageId);
    if (!record || record.headerScheduled) return;
    record.headerScheduled = true;
    scheduleUiFrame(() => {
      record.headerScheduled = false;
      if (streamingObservers.get(messageId) !== record || !record.target.isConnected) return;
      const message = getChatArray()?.[messageId];
      if (!message || message !== record.message || message.is_user) return;

      const messageDom = findMessageDom(messageId);
      // 公开裁决的流式面板仍由原来的提取路径管理。
      if (!messageDom || messageDom.hasAttribute('data-qqz-reasoning-streaming')) return;
      const details = messageDom.querySelector('.mes_reasoning_details');
      const hostState = messageDom.getAttribute('data-reasoning-state') || details?.getAttribute('data-state');
      if (hostState === 'hidden') return;
      if (!message.extra?.reasoning && !record.reasoningTarget?.textContent?.trim()) return;

      const state = hostState === 'thinking' || hostState === 'done'
        ? hostState
        : (message.extra?.reasoning_duration || String(message.mes ?? '').trim() ? 'done' : 'thinking');
      // 原生状态与展开/折叠由酒馆管理；这里只刷新标题和元信息。
      renderReasoningHeader(messageDom, state, FIXED_REASONING_TITLE, extractTpInfo(String(message.mes ?? '')));
    });
  }

  function ensureStreamingObserver(messageId) {
    const messageDom = findMessageDom(messageId);
    const messageTextDom = messageDom?.querySelector?.('.mes_text');
    const nativeReasoningDom = messageDom?.querySelector?.('.mes_reasoning');
    if (!messageTextDom || typeof MutationObserver === 'undefined') return;

    const current = streamingObservers.get(messageId);
    const message = getChatArray()?.[messageId];
    if (current?.target === messageTextDom && current?.reasoningTarget === nativeReasoningDom && current?.message === message) return;
    current?.observer?.disconnect?.();

    const observeContent = () => {
      observer.observe(messageTextDom, { childList: true, subtree: true, characterData: true });
      if (nativeReasoningDom) observer.observe(nativeReasoningDom, { childList: true, subtree: true, characterData: true });
    };
    const observer = new MutationObserver((mutations) => {
      // 暂停观察自身对 .mes_text 的清洗写入，防止递归触发。
      observer.disconnect();
      try {
        if (mutations.some(({ target }) => target === messageTextDom || messageTextDom.contains(target))) {
          applyStreamingRawText(messageId);
        }
        scheduleStreamingHeader(messageId);
      } finally {
        if (streamingObservers.get(messageId)?.observer === observer && messageTextDom.isConnected) {
          observeContent();
        }
      }
    });

    observeContent();
    streamingObservers.set(messageId, { observer, target: messageTextDom, reasoningTarget: nativeReasoningDom, message, headerScheduled: false });
  }

  function handleStreamingText(rawText) {
    const chat = getChatArray();
    if (!chat?.length || typeof rawText !== 'string') return;

    for (let i = chat.length - 1; i >= 0; i--) {
      if (!chat[i] || chat[i].is_user) continue;
      streamingRawText.set(i, rawText);
      ensureStreamingObserver(i);
      scheduleStreamingHeader(i);
      return;
    }
  }

  function bindEvents() {
    if (typeof eventOn === 'function' && typeof tavern_events !== 'undefined') {
      eventOn(tavern_events.MESSAGE_UPDATED, (messageId) => {
        scheduleApplyMessage(messageId);
      });

      eventOn(tavern_events.MESSAGE_RECEIVED, (messageId) => {
        const id = Number(messageId);
        applyStreamingRawText(id, false);
        stopStreamingObserver(id);
        pendingMessageIds.delete(id);
        applyReasoningToMessage(id, true);
        finalizeStreamingMessageDom(id, getChatArray()?.[id]);
      });


      eventOn(tavern_events.CHAT_CHANGED, () => {
        stopAllStreamingObservers();
        streamTickScheduled = false;
        pendingMessageIds.clear();
        injectConfig(); // 切换聊天时再次确保配置注入
        setTimeout(applyReasoningToAllMessages, 50);
      });

      eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, (messageId) => {
        applyReasoningToMessage(messageId);
      });

      // 参数是当前完整流文本，且事件早于酒馆本轮 DOM 写入。
      eventOn(tavern_events.STREAM_TOKEN_RECEIVED, (rawText) => {
        handleStreamingText(rawText);
      });
    } else {
      log('eventOn/tavern_events not available');
    }
  }

  function init() {
    injectConfig();
    injectStyle();
    bindReasoningEditToggleGuard(document);
    bindReasoningEditToggleGuard(getTopDocument());
    bindEvents();

    setTimeout(applyReasoningToAllMessages, 100);
    setTimeout(applyReasoningToAllMessages, 800);

    $(window).on('pagehide', () => {
      stopAllStreamingObservers();
      unbindReasoningEditToggleGuards();
      removeStyle();
    });
    log('loaded', { scriptId: SCRIPT_ID, debug: DEBUG });
  }

  $(() => init());
})();

// Paste this loader into the existing 命定预设助手 script (preserve its UUID and variables).
const version = '3.11.0';
const url = `https://cdn.jsdelivr.net/gh/rhys-3/destined-journey-assistant@v${version}/dist/destined-journey-assistant.js`;
let loading = false;
let attempt = 0;
let retryEvent;
async function loadAssistant() {
  if (loading) return;
  loading = true;
  try {
    await import(attempt ? `${url}?retry=${attempt}` : url);
    retryEvent?.stop?.();
    updateScriptButtonsWith(buttons => buttons.filter(button => button.name !== '重新加载命定预设助手'));
  } catch (error) {
    console.error(`[命定预设助手 v${version}] 加载失败`, error);
    toastr.error(`命定预设助手 v${version} 加载失败：${error.message}。可点击“重新加载命定预设助手”重试。`);
    updateScriptButtonsWith(buttons => [...buttons.filter(button => button.name !== '重新加载命定预设助手'), { name: '重新加载命定预设助手', visible: true }]);
    retryEvent ??= eventOn(getButtonEvent('重新加载命定预设助手'), () => { attempt++; return loadAssistant(); });
  } finally {
    loading = false;
  }
}
await loadAssistant();

